
.affinity-panel {
  padding: 10px;
  background: var(--cp-bg-panel);
  border-bottom: 1px solid var(--cp-border);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.stage-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}

.stage-label {
  font-family: var(--font-mono);
  color: var(--cp-text-dim);
  font-size: 0.7rem;
  letter-spacing: 1px;

  &::after {
    content: ':';
  }
}

.stage-value {
  font-family: var(--font-cyber);
  font-weight: 700;
  font-size: 0.85rem;
  letter-spacing: 1px;

  &.stage-hostile {
    color: var(--cp-red);
    text-shadow: 0 0 6px rgba(255, 51, 51, 0.4);
  }
  &.stage-cautious {
    color: #ff8c00;
    text-shadow: 0 0 6px rgba(255, 140, 0, 0.4);
  }
  &.stage-attached {
    color: var(--cp-cyan);
    text-shadow: 0 0 6px rgba(0, 240, 255, 0.4);
  }
  &.stage-obsessed {
    color: var(--cp-magenta);
    text-shadow: 0 0 6px rgba(255, 45, 120, 0.4);
  }
  &.stage-redeemed {
    color: var(--cp-green);
    text-shadow: 0 0 6px rgba(57, 255, 20, 0.4);
  }
}

.danger-tag {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 0.65rem;
  padding: 1px 6px;
  border: 1px solid;
  letter-spacing: 1px;

  &.danger-critical {
    color: var(--cp-red);
    border-color: var(--cp-red);
    background: rgba(255, 51, 51, 0.1);
    animation: dangerBlink 1s infinite;
  }
  &.danger-high {
    color: #ff6b35;
    border-color: #ff6b35;
    background: rgba(255, 107, 53, 0.08);
  }
  &.danger-warn {
    color: var(--cp-yellow);
    border-color: var(--cp-yellow);
    background: rgba(255, 215, 0, 0.06);
  }
  &.danger-low {
    color: var(--cp-text-dim);
    border-color: var(--cp-border);
  }
  &.danger-safe {
    color: var(--cp-green);
    border-color: var(--cp-green);
    background: rgba(57, 255, 20, 0.06);
  }
}

@keyframes dangerBlink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

.bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bar-label {
  font-family: var(--font-cyber);
  font-size: 0.75rem;
  font-weight: 600;
  min-width: 58px;

  &.cyan {
    color: var(--cp-cyan);
  }
  &.red {
    color: var(--cp-red);
  }
  &.magenta {
    color: var(--cp-magenta);
  }
}

.bar-track {
  flex: 1;
  height: 6px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--cp-border);
  position: relative;
  overflow: hidden;
}

.bar-fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  transition: width 0.4s ease;

  &.cyan {
    background: linear-gradient(90deg, rgba(0, 240, 255, 0.6), var(--cp-cyan));
    box-shadow: 0 0 6px rgba(0, 240, 255, 0.3);
  }
  &.red {
    background: linear-gradient(90deg, rgba(255, 51, 51, 0.6), var(--cp-red));
    box-shadow: 0 0 6px rgba(255, 51, 51, 0.3);
  }
  &.magenta {
    background: linear-gradient(90deg, rgba(255, 45, 120, 0.6), var(--cp-magenta));
    box-shadow: 0 0 6px rgba(255, 45, 120, 0.3);
  }
}

.bar-value {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  min-width: 28px;
  text-align: right;

  &.cyan {
    color: var(--cp-cyan);
  }
  &.red {
    color: var(--cp-red);
  }
  &.magenta {
    color: var(--cp-magenta);
  }
}
