
.world-section {
  border-bottom: 1px solid var(--cp-border);
  padding: 10px;
  background: var(--cp-bg-panel);
}

.header-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--cp-border);
}

.sys-tag {
  font-family: var(--font-mono);
  color: var(--cp-cyan);
  font-size: 0.75rem;
  letter-spacing: 2px;
  text-shadow: 0 0 8px rgba(0, 240, 255, 0.4);
}

.sys-ver {
  font-family: var(--font-mono);
  color: var(--cp-text-dim);
  font-size: 0.65rem;
}

.meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 8px;
}

.meta-item {
  display: flex;
  gap: 6px;
  align-items: baseline;
}

.meta-label {
  font-family: var(--font-mono);
  color: var(--cp-text-dim);
  font-size: 0.7rem;
  letter-spacing: 1px;

  &::after {
    content: ':';
  }
}

.meta-value {
  font-family: var(--font-mono);
  color: var(--cp-text-bright);
  font-size: 0.8rem;
}

.meta-value.loc {
  color: var(--cp-cyan);
}

.meta-value.weather {
  color: var(--cp-text);
}

.event-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.event-item {
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 3px 6px;
  background: rgba(0, 240, 255, 0.03);
  border-left: 2px solid var(--cp-cyan);
  font-size: 0.78rem;
}

.event-marker {
  color: var(--cp-cyan);
  font-size: 0.65rem;
}

.event-name {
  color: var(--cp-text-bright);
  font-weight: 600;
  white-space: nowrap;
}

.event-desc {
  color: var(--cp-text-dim);
  font-size: 0.72rem;
}

@media (max-width: 600px) {
  .meta-row {
    flex-direction: column;
    gap: 4px;
  }
}
