
.cyber-card {
  width: 100%;
  max-width: 720px;
  background: var(--cp-bg-deep);
  border: 1px solid var(--cp-border);
  box-shadow:
    0 0 15px rgba(0, 240, 255, 0.08),
    inset 0 0 30px rgba(0, 0, 0, 0.5);
  display: flex;
  flex-direction: column;
  font-family: var(--font-cyber);
  color: var(--cp-text);
  font-size: 13px;
  line-height: 1.4;
  margin: 0 auto;
  position: relative;
  overflow: hidden;
}

.cyber-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--cp-cyan), transparent);
  animation: borderGlow 3s ease-in-out infinite;
}

@keyframes borderGlow {
  0%,
  100% {
    opacity: 0.5;
  }
  50% {
    opacity: 1;
  }
}

.scanline {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(0, 240, 255, 0.015) 2px,
    rgba(0, 240, 255, 0.015) 4px
  );
  pointer-events: none;
  z-index: 10;
}

.content-area {
  padding: 10px;
  min-height: 0;
}

.tab-pane {
  display: none;
  animation: cyberFade 0.3s;
}

.tab-pane.active {
  display: block;
}

@keyframes cyberFade {
  from {
    opacity: 0;
    transform: translateY(3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
